function kitFold(host,d,open){var x=document.createElement('details');x.className='fold';if(open)x.open=true;x.innerHTML='<summary><div class="fold-title"><h2>'+kEsc(d.title)+'</h2><span class="fold-verdict">'+kEsc(d.verdict)+'</span></div><span class="chip'+(d.tone?' '+d.tone:'')+'">'+kEsc(d.chip)+'</span></summary><div class="fold-body"><p>'+kEsc(d.body)+'</p></div>';host.appendChild(x);return x}
